targets.expr:
sum(
  increase(
    http_request_duration_seconds_bucket{
      job="nestjs",
      le="+Inf"
    }[5m]
  )
)
-
sum(
  increase(
    http_request_duration_seconds_bucket{
      job="nestjs",
      le="1"
    }[5m]
  )
)

100 *
(
1 -
node_filesystem_avail_bytes{
    job="node",
    mountpoint="/"
}
/
node_filesystem_size_bytes{
    job="node",
    mountpoint="/"
}
)

sum by(name)(
rate(
container_cpu_usage_seconds_total{
    job="cadvisor",
    image!=""
}[5m])
)

topk(
10,
sum by(name)(
rate(
container_cpu_usage_seconds_total{
    job="cadvisor",
    image!=""
}[5m])
)
)

topk(
10,
sum by(name)(
container_memory_usage_bytes{
    job="cadvisor",
    image!=""
}
)
)
